ALTER TABLE store_delivery_assignments ADD COLUMN dispatched_at timestamptz;
UPDATE store_order_details d SET payload=jsonb_set(payload,'{tracking}',jsonb_build_object('stage','delivered','mode','staff_dispatch','history',COALESCE(payload->'tracking'->'history','[]'::jsonb)||jsonb_build_array(jsonb_build_object('stage','delivered','at',((payload->>'confirmedAt')::timestamptz+interval '24 hours'))))) FROM orders o WHERE o.id=d.order_id AND o.status='confirmed' AND (d.payload->>'confirmedAt')::timestamptz<=now()-interval '24 hours';
UPDATE store_order_details d SET payload=jsonb_set(payload,'{tracking}',jsonb_build_object('stage','shipped','mode','staff_dispatch','history',jsonb_build_array(jsonb_build_object('stage','confirmed','at',payload->>'confirmedAt'),jsonb_build_object('stage','shipped','at',(payload->>'confirmedAt')::timestamptz+interval '1 hour')))) FROM orders o WHERE o.id=d.order_id AND o.status='confirmed' AND d.payload->'tracking'->>'stage'='out_for_delivery' AND d.payload->'deliveryPerson' IS NULL;
UPDATE store_delivery_assignments a SET dispatched_at=a.assigned_at FROM store_order_details d WHERE a.order_id=d.order_id AND a.released_at IS NULL AND d.payload->'tracking'->>'stage' IN ('out_for_delivery','delivered');
